// Compiled configuration, generated by scripts/compile.ts (network.json) and
// scripts/deploy.ts (deployed.json), bundled into the Worker at build time.
import type { Risk, RiskCeiling } from "./risk";
import network from "./generated/network.json";
import deployed from "./generated/deployed.json";

export interface ActionKind {
  risk: Risk;
  executor: "github" | "discord" | "discord_ops" | "discord_dm" | "vimeo" | "manual" | "task";
  /** Executed at once, without the owner, after the gateway's own safety checks. Only github.approve_ci and github.review. */
  auto?: boolean;
}

/** config/review.yaml: how Mira reviews (decisions 35 and 36). */
export interface ReviewConfig {
  areas: Record<string, string>;
  max_findings: number;
  max_nits: number;
  tone: { first_time: string; maintainer: string; default: string };
  risk: { high_over_lines: number; high_paths: string[]; low_max_lines: number; low_paths: string[] };
  path_rules: { glob: string; note: string; repo?: string }[];
}

export interface Person {
  name: string;
  /** From people.yaml: any of owner, tsc_member, maintainer. Labels only; they grant no rights. */
  roles: string[];
  /** Full repo names, e.g. accordproject/concerto */
  maintains?: string[];
  github?: string;
  discord?: string;
  telegram?: string;
}

export interface AgentConfig {
  name: string;
  title: string;
  phase: number;
  requestable: string[];
  /** The model of the agent's default tier in models.yaml. */
  model?: string;
}

export interface NetworkConfig {
  current_phase: number;
  timezone: string;
  monthly_credit_usd: number;
  sandbox_repo: string;
  /** The network's own code (decision 51); never one of `repos`. */
  network_repo: string;
  repos: string[];
  action_kinds: Record<string, ActionKind>;
  agents: Record<string, AgentConfig>;
  people?: Person[];
  /** Channel ids the bot posts to (config/discord.yaml, decision 17A). */
  discord_channels?: { announcements?: string; agent_ops?: string };
  /** Highest risk the owner may approve from Discord (decision 15B). Absent = Telegram only. */
  discord_approval_max_risk?: Exclude<RiskCeiling, "high">;
  /** Where approval cards go. discord: Discord-approvable cards go only to Discord. Absent = both. */
  approvals_app?: "discord" | "telegram" | "both";
  /** Merge proposals from Mira must come from a fresh review-check session (decision 2A). */
  review_check_required?: boolean;
  /** Review settings; absent in old builds, when the gateway falls back to DEFAULT_REVIEW. */
  review?: ReviewConfig;
  /** Messages each member may send the agents per day (network.yaml budgets). Absent = 20. */
  member_daily_messages?: number;
  /** network.schedules_enabled: whether agents run without being asked. Absent = off. */
  schedules_enabled?: boolean;
  /**
   * Waking Ada when a task ends blocked or an approved decision fails (decision 50):
   * wakes per UTC day, and each wake's session budget. Absent or 0 wakes = off.
   */
  follow_up?: { daily_wakes: number; budget_cents: number };
  /**
   * Starting Mira when GitHub events call for it (decision 62): wakes per UTC day and
   * each wake's session budget, by trigger. Absent, or 0 a day, turns that trigger off.
   */
  github_wakes?: Partial<Record<"review" | "merge" | "first_response", { daily: number; budget_cents: number }>>;
  /** The self-improvement loop (decision 55). `since` null = off; task_cents are Mandla's session budgets. */
  self_improvement?: {
    since: string | null;
    stale_days: number;
    /** Days between proposals for one target, and the evidence rule; defaults 7, 10 and 14. */
    proposal_gap_days?: number;
    min_decided?: number;
    min_days?: number;
    commit_author: { name: string; email: string };
    task_cents: { small: number; large: number };
  };
  /** Model ids by tier, from models.yaml, for sessions the gateway starts on a stronger model. */
  model_tiers?: Record<string, string>;
}

export interface DeployedAgent {
  agent_id: string;
  environment_id: string;
  vault_ids: string[];
  memory_store_ids: string[];
  session_budget_cents: number;
}

export interface DeployedConfig {
  agents: Record<string, DeployedAgent>;
  deployments: Record<string, { id: string; agent: string }>;
}

export const NETWORK = network as unknown as NetworkConfig;
export const DEPLOYED = deployed as unknown as DeployedConfig;

export function isActivePhase(agent: string, cfg: NetworkConfig = NETWORK): boolean {
  const a = cfg.agents[agent];
  return !!a && a.phase <= cfg.current_phase;
}

export function agentByManagedId(agentId: string, dep: DeployedConfig = DEPLOYED): string | undefined {
  return Object.entries(dep.agents).find(([, a]) => a.agent_id === agentId)?.[0];
}
